const PUBLIC_GEO_EXACT_ROUTES = new Set(['/', '/data', '/meta-report', '/erp', '/crm', '/automation', '/web-design', '/llms.txt', '/llms-full.txt', '/ai.txt', '/robots.txt', '/sitemap.xml']);
const PROTECTED_WORKSPACE_PREFIXES = ['/data/', '/meta-report/', '/api/v1/', '/v1/', '/assets/'];
const BLOCKED_SCRAPER_UA_RE = /(HTTrack|WebCopier|SiteSucker|Firecrawl|Apify|Diffbot|Scrapy|HeadlessChrome|Playwright|Puppeteer|Bytespider|CCBot)/i;
const VERIFIED_GEO_BOT_UA_RE = /(Googlebot|Bingbot|OAI-SearchBot|ChatGPT-User|PerplexityBot|Claude-SearchBot|ClaudeBot)/i;

const TDM_PROPRIETARY_HEADERS: Record<string, string> = {
  'TDM-Reservation': '1',
  'TDM-Policy': 'https://domation.net/.well-known/tdmrep.json',
  'Content-Usage': 'train-ai=n, ai=n',
  'X-Robots-Tag': 'noindex, nofollow, noarchive, nosnippet, noai, noimageai',
  'X-Content-License': 'PROPRIETARY-COMMERCIAL-INTERNAL-STRICTLY-PROHIBITED',
  'X-AI-Agent-Policy': 'Anti-Agent Guard Active: UI/UX cloning, DOM scraping & algorithm extraction strictly forbidden. Policy: https://domation.net/ai.txt',
};

function isProtectedWorkspacePath(pathname: string): boolean {
  if (pathname.endsWith('.map')) return true; // Chan tuyet doi JS Source Map
  return PROTECTED_WORKSPACE_PREFIXES.some((prefix) => pathname.startsWith(prefix));
}

function hasBrowserIntegritySignals(headers: Headers): boolean {
  const secFetchSite = headers.get('sec-fetch-site');
  const acceptLang = headers.get('accept-language');
  const secChUa = headers.get('sec-ch-ua') || '';
  if (/HeadlessChrome/i.test(secChUa)) return false;
  return Boolean(acceptLang && (secFetchSite === 'same-origin' || secFetchSite === 'same-site' || secFetchSite === 'none'));
}

export async function antiAgentEdgeGuard(req: Request, verifyCrawlerIp: (ip: string, ua: string) => Promise<boolean>): Promise<Response> {
  const url = new URL(req.url);
  const pathname = url.pathname;
  const ua = req.headers.get('user-agent') || '';
  const clientIp = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || '';

  // 1. Luon cam dung cac cong cu cloner/scraper thuan tuy (ke ca trang public)
  if (BLOCKED_SCRAPER_UA_RE.test(ua)) {
    return new Response(JSON.stringify({ error: 'FORBIDDEN_AUTOMATED_SCRAPER', policy: 'https://domation.net/ai.txt' }), {
      status: 403,
      headers: { 'Content-Type': 'application/json; charset=utf-8', ...TDM_PROPRIETARY_HEADERS },
    });
  }

  // 2. Khoa chat Workspace noi bo, API va JS bundles truoc AI Browser Agent & Bot gia danh
  if (isProtectedWorkspacePath(pathname)) {
    const isSpoofingSearchBot = VERIFIED_GEO_BOT_UA_RE.test(ua);
    const hasValidSession = Boolean(req.headers.get('authorization') || req.headers.get('cookie')?.includes('dom_session='));

    if (isSpoofingSearchBot || (!hasBrowserIntegritySignals(req.headers) && !hasValidSession)) {
      return new Response('403 Forbidden: Proprietary SaaS Workspace Protected by TDM-Reservation: 1 & Anti-Agent Guard.', {
        status: 403,
        headers: { 'Content-Type': 'text/plain; charset=utf-8', ...TDM_PROPRIETARY_HEADERS },
      });
    }
  }

  // 3. Mo lan GEO cho Search Crawler chinh danh tren trang cong khai (/ , /boost/*, /llms.txt)
  if (PUBLIC_GEO_EXACT_ROUTES.has(pathname) || pathname.startsWith('/boost')) {
    if (VERIFIED_GEO_BOT_UA_RE.test(ua)) {
      const ipTrusted = await verifyCrawlerIp(clientIp, ua);
      if (!ipTrusted) {
        return new Response('403 Forbidden: Unverified Crawler Spoofing Search Bot UA.', { status: 403, headers: TDM_PROPRIETARY_HEADERS });
      }
    }
  }

  return new Response(null, { status: 200, headers: { 'x-middleware-next': '1', 'TDM-Policy': 'https://domation.net/.well-known/tdmrep.json' } });
}
